import numpy as np
Pb={'1':np.ones_like(P),'P':P,'P2':P**2,'P3':P**3,'sP':np.sqrt(P),'PlnP':P*np.log(P)}
Tb={'1':np.ones_like(t),'s':np.sqrt(t),'s1':np.sqrt(1+t),'t':t,'t15':t**1.5,'s1t':np.sqrt(t)*np.sqrt(1+t)}
names=[];cols=[]
for a in Tb:
    for b in Pb:
        names.append(a+'*'+b); cols.append(Tb[a]*Pb[b])
A=np.array(cols).T
c,_,_,_=np.linalg.lstsq(A,dP_dt,rcond=None)
r=dP_dt-A@c
print('nmse',np.mean(r**2)/np.var(dP_dt))
for n,v in zip(names,c): print(n,round(v,5))
